// WhatsApp Module Handler
const inputData = $input.first().json;
const configs = inputData.enabled_modules || {};
const whatsappConfig = configs.whatsapp || {};

// Check if WhatsApp is enabled
if (!whatsappConfig || Object.keys(whatsappConfig).length === 0) {
  return { json: { error: 'WhatsApp module not enabled', status: 'disabled' } };
}

// Process WhatsApp message
return {
  json: {
    ...inputData,
    config: whatsappConfig,
    module: 'whatsapp',
    status: 'processing'
  }
};

