// Merge all module outputs
const items = $input.all();
const processedItems = items.map(item => ({
  json: {
    ...item.json,
    processed_at: new Date().toISOString(),
    execution_time_ms: Date.now() - (item.json.start_time || Date.now())
  }
}));

return processedItems;
